// Normalize an incoming email application into the common candidate shape
const out = [];
for (const item of $input.all()) {
  const j = item.json;

  // Basic parsing - adjust regex/logic to match your actual email format
  const fromText = j.from || j.From || '';
  const emailMatch = fromText.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  const email = emailMatch ? emailMatch[0] : '';
  const nameMatch = fromText.match(/^\"?([^\"<]+)\"?\s*</);
  const name = nameMatch ? nameMatch[1].trim() : (email ? email.split('@')[0] : 'Unknown');

  const subject = j.subject || j.Subject || '';
  const roleMatch = subject.match(/applying for[:\-]?\s*(.+)/i);
  const roleApplied = roleMatch ? roleMatch[1].trim() : (subject || 'Not specified');

  out.push({
    json: {
      name,
      email,
      phone: '',
      source: 'email',
      role_applied: roleApplied,
      resume_text: j.text || j.textHtml || '',
      resume_url: '',
      applied_at: new Date().toISOString()
    }
  });
}
return out;

// Normalize a Google Form row into the common candidate shape
// Adjust the column names below to exactly match your Google Form's sheet headers
const out = [];
for (const item of $input.all()) {
  const j = item.json;

  out.push({
    json: {
      name: j['Full Name'] || j['Name'] || '',
      email: j['Email'] || j['Email Address'] || '',
      phone: j['Phone'] || j['Phone Number'] || '',
      source: 'form',
      role_applied: j['Role Applied For'] || j['Position'] || 'Not specified',
      resume_text: j['Resume Text'] || '',
      resume_url: j['Resume Link'] || j['Resume URL'] || '',
      applied_at: j['Timestamp'] ? new Date(j['Timestamp']).toISOString() : new Date().toISOString()
    }
  });
}
return out;

// Parse the AI response, apply scoring bands, and attach classification
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let atsScore = 0;
  let reasoning = '';

  try {
    const content = j.choices?.[0]?.message?.content;
    const parsed = JSON.parse(content);
    atsScore = Number(parsed.ats_score) || 0;
    reasoning = parsed.reasoning || '';
  } catch (e) {
    // AI call failed or returned bad JSON -> fail-safe to manual review, don't silently drop the candidate
    atsScore = 0;
    reasoning = 'AI scoring failed - flagged for manual review';
  }

  let classification;
  if (atsScore >= 75) classification = 'Strong';
  else if (atsScore >= 50) classification = 'Average';
  else classification = 'Weak';

  out.push({
    json: {
      ...item.json,
      ats_score: atsScore,
      classification,
      ai_reasoning: reasoning
    }
  });
}
return out;
